index c7bfbf8..1bdf49f 100644
--- a/overrides/app/theme/components/index.ts
+++ b/overrides/app/theme/components/index.ts
@@ -31,6 +31,7 @@ import { ZimmSlideIndicator } from 'app/components/ui-kits/molecules/zimmSlideIn
 import { ZimmSizeChip } from 'app/components/ui-kits/atoms/zimmSizeChip/zimmSizeChip.css';
 import { ZimmSizeChipGroup } from 'app/components/ui-kits/molecules/zimmSizeChipGroup/zimmSizeChipGroup.css';
 import { ZimmProductCardMedia } from 'app/components/ui-kits/molecules/zimmProductCardMedia/zimmProductCardMedia.css';
+import { ZimmProductCardContent } from 'app/components/ui-kits/molecules/zimmProductCardContent/zimmProductCardContent.css';

 export const components = {
   Button,
@@ -66,4 +67,5 @@ export const components = {
   ZimmSizeChip,
   ZimmSizeChipGroup,
   ZimmProductCardMedia,
+  ZimmProductCardContent,
 };

1	import React from 'react'; // required for JSX transform in this project's tsconfig
2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { Link as RouteLink } from 'react-router-dom';
4	
5	const ZIMM_COLOUR_SWATCH_RECIPE = 'ZimmColourSwatch';
6	
7	// Same import base SFCC's own swatch-group/swatch.jsx uses for its `RouteLink` — a router
8	// `Link` is what actually delivers "URL updates without a full page reload": it pushes history
9	// rather than navigating the document. There is no overrides/.../link equivalent to reuse
10	// instead — confirmed none exists for this.
11	const ColourSwatchLink = chakra(RouteLink);
12	
13	type ZimmColourSwatchProps = {
14	  /** Colour display name. Not rendered as visible text — used as the accessible name (`aria-label`). */
15	  name: string;
16	  /**
17	   * Fully resolved image URL for this colour's swatch fill. Resolution is the caller's job —
18	   * this component performs no SFCC-shape lookup of its own.
19	   */
20	  imageUrl: string;
21	  /**
22	   * Destination URL for this colour variation. Absent for the quick-view-modal path, where
23	   * SFCC's own `useVariationAttributes` returns `href: null` and the swatch must not navigate.
24	   */
25	  href?: string;
26	  /**
27	   * Selection callback for the linkless path (no `href`). Called on click and arrow-key
28	   * navigation from the parent group. Ignored when `href` is provided — selection is handled
29	   * by the router link in that case.
30	   */
31	  onClick?: () => void;
32	  /** Whether this is the currently selected colour. */
33	  isSelected: boolean;
34	  /**
35	   * Whether this swatch is reachable via Tab (`tabIndex={0}`) vs. removed from the tab order
36	   * (`tabIndex={-1}`) — the caller drives a roving tabindex across the swatch group.
37	   */
38	  isFocusable: boolean;
39	  /**
40	   * 1-indexed position of this swatch within the full offered colour set. Together with
41	   * `setSize`, produces correct "N of M" SR announcements even when only a page-worth of
42	   * swatches is visually present — `overflow: hidden` can cause some AT to under-count the
43	   * implicit set size.
44	   */
45	  posInSet?: number;
46	  /** Total number of offered colours in the group. Companion to `posInSet`. */
47	  setSize?: number;
48	};
49	
50	/**
51	 * Atom — a single colour swatch in a PDP colour-variation list: a clickable rectangle filled
52	 * with that colour's product photo, radio semantics (one selection out of the group), and a
53	 * router `Link` when a destination URL exists so selecting a colour updates the URL without a
54	 * full page reload.
55	 *
56	 * Purely presentational — no data-fetching hook of any kind. SFCC data resolution (building
57	 * `imageUrl`/`href` from a product's variation attributes) happens at the page level, not this
58	 * atom.
59	 */
60	export const ZimmColourSwatch = ({
61	  name,
62	  imageUrl,
63	  href,
64	  onClick,
65	  isSelected,
66	  isFocusable,
67	  posInSet,
68	  setSize,
69	}: ZimmColourSwatchProps) => {
70	  const styles = useMultiStyleConfig(ZIMM_COLOUR_SWATCH_RECIPE, { selected: isSelected });
71	
72	  // The dynamic URL genuinely cannot live in the static recipe file, so this one dynamic `__css`
73	  // spread is the correct, deliberate exception — the same shape already used in
74	  // footer/footerNavColumn/index.tsx, an established pattern in this codebase.
75	  // backgroundImage is dynamic per swatch — cannot live in the static recipe file. The
76	  // data-image-url attribute is a test hook (element.style is not populated by emotion in JSDOM).
77	  const image = (
78	    <chakra.span __css={styles.image} style={{ backgroundImage: `url(${imageUrl})` }} data-image-url={imageUrl} />
79	  );
80	
81	  /*
82	   * Deliberately no `backgroundColor={name.toLowerCase()}` here, unlike base SFCC's own
83	   * `renderDefaultVariationAttribute` (product-view/index.jsx, and our own extraction of it in
84	   * product-view/index.tsx). Three reasons this stays out, permanently, not an oversight to
85	   * "fix" back in later:
86	   *   1. It uses the colour's display name as a raw CSS colour keyword — "Ivory" resolves as a
87	   *      real CSS colour, "Bay Blue" does not — which is both unauditable by `audit:tokens` and
88	   *      against this codebase's no-raw-design-value rule.
89	   *   2. In base it exists to tint the swatch behind a *missing* product image. This component is
90	   *      only ever rendered for colour variations that already have a populated image — the
91	   *      caller filters out any variation without one before rendering this component at all —
92	   *      so there is never a missing image for a fallback tint to show behind.
93	   *   3. Even if one slipped through, `background-size: cover` on the image (see the recipe's
94	   *      `image` part) would hide any tint sitting behind it regardless.
95	   */
96	  if (href) {
97	    return (
98	      <ColourSwatchLink
99	        to={href}
100	        __css={styles.swatch}
101	        role="radio"
102	        aria-checked={isSelected}
103	        aria-label={name}
104	        aria-posinset={posInSet}
105	        aria-setsize={setSize}
106	        tabIndex={isFocusable ? 0 : -1}
107	        data-testid="colour-swatch"
108	      >
109	        {image}
110	      </ColourSwatchLink>
111	    );
112	  }
113	
114	  // Linkless path (quick-view): render a button so the swatch is keyboard-focusable and
115	  // carries the same radio semantics as the href path — no navigation, selection via onClick.
116	  return (
117	    <chakra.button
118	      __css={styles.swatch}
119	      type="button"
120	      role="radio"
121	      aria-checked={isSelected}
122	      aria-label={name}
123	      aria-posinset={posInSet}
124	      aria-setsize={setSize}
125	      tabIndex={isFocusable ? 0 : -1}
126	      onClick={onClick}
127	      data-testid="colour-swatch"
128	    >
129	      {image}
130	    </chakra.button>
131	  );
132	};
133	
134	export type { ZimmColourSwatchProps };
135	export default ZimmColourSwatch;
136

